               cs18*(-at1(3, 1)*cs547 - at2(3, 3, 1)*cs543 - at3(3, 3, 3, 1)*cs36 - at1(3, &
               2)*cs539 - at2(3, 3, 2)*cs520 + (1.0_wp/2.0_wp)*at3(3, 3, 3, 2)*cs0*cs9*ps0(1)*s_3 &
               + 2.0_wp*at2(3, 3, 3)*cs0*cs118*cs148*cs56 - at3(3, 3, 3, 3)*cs27 - at1(3, 4)*cs529 &
